-- Categorías de vendedor. No mueve las categorías de construcción ya usadas por publicaciones.
-- No inserta productos, proveedores ni precios.

alter table categories add column if not exists icon text;
alter table categories add column if not exists description text not null default '';
alter table categories add column if not exists is_featured boolean not null default false;
alter table categories add column if not exists sort_order integer not null default 1000;
alter table categories add column if not exists synonyms text not null default '';

create table if not exists business_categories (
  business_id text not null references businesses (id) on delete cascade,
  category_id text not null references categories (id),
  created_at timestamptz not null default now(),
  primary key (business_id, category_id)
);

values ('seller_category_limit', '10'::jsonb)
on conflict (key) do nothing;

on conflict (id) do nothing;
